def _drop_excursion(coords: List[List[float]], start: int, end: int) -> List[List[float]]:
    """같은 지점을 두 번 지나는 곁가지(coords[start]==coords[end]) 구간을 떼어낸다.

    같은 점에서 갈라졌다 돌아오는 구간이라 떼어도 경로가 끊기거나 점프하지 않는다.
    """
    if coords[start] != coords[end]:
        raise ValueError("곁가지의 시작과 끝은 같은 좌표여야 한다")
    return coords[:start] + coords[end:]


