def _haversine_m(lat1: float, lon1: float, lat2: float, lon2: float) -> float:
    R = 6371000.0
    phi1, phi2 = math.radians(lat1), math.radians(lat2)
    dphi = math.radians(lat2 - lat1)
    dlam = math.radians(lon2 - lon1)
    a = math.sin(dphi / 2.0) ** 2 + math.cos(phi1) * math.cos(phi2) * math.sin(dlam / 2.0) ** 2
    return 2.0 * R * math.atan2(math.sqrt(a), math.sqrt(1.0 - a))

import json
from pathlib import Path
from shapely.geometry import shape, LineString, Polygon

_PARK_POLYGONS_CACHE: Optional[Dict[str, Polygon]] = None

def load_pilot_park_polygons() -> Dict[str, Polygon]:
    """fixtures/park_polygons_pilot.json 에서 4대 공원 경계 폴리곤을 로드."""
    global _PARK_POLYGONS_CACHE
    if _PARK_POLYGONS_CACHE is not None:
        return _PARK_POLYGONS_CACHE

    fixture_path = Path(__file__).resolve().parent.parent / "fixtures" / "park_polygons_pilot.json"
    polys: Dict[str, Polygon] = {}
    if fixture_path.exists():
        with open(fixture_path, "r", encoding="utf-8") as f:
            data = json.load(f)
            for feat in data.get("features", []):
                p_id = feat.get("properties", {}).get("park_id")
                geom = feat.get("geometry")
                if p_id and geom:
                    polys[p_id] = shape(geom)
    _PARK_POLYGONS_CACHE = polys
    return polys

def is_route_inside_park_boundary(coords: List[List[float]], park_id: str) -> bool:
    """주어진 좌표열이 해당 공원 경계 폴리곤 내부에 완전히 포함되는지 검사."""
    polys = load_pilot_park_polygons()
    poly = polys.get(park_id)
    # 경계 데이터가 없거나 좌표가 부족하면 "안전하다"고 단정하지 않고 실패로 처리한다.
    if poly is None or len(coords) < 2:
        return False
    line = LineString(coords)
    # 완충 0.0005도(약 50m) 여유 허용
    return poly.buffer(0.0005).contains(line)

def resolve_pilot_park_key(
    origin_lat: float,
    origin_lon: float,
    max_radius_m: float = 2500.0,
    pilot_park_id: Optional[str] = None,
) -> Optional[str]:
    """pilot_park_id 가 있으면 우선 사용하고, 없으면 출발 좌표에서 가장 가까운 거점 공원 키를 반환."""
    if pilot_park_id and pilot_park_id in PILOT_PARK_COORDS_MAP:
        return pilot_park_id
    candidates = []
    for park_key, (c_lat, c_lon, _name) in PILOT_PARK_CENTERS.items():
        dist = _haversine_m(origin_lat, origin_lon, c_lat, c_lon)
        if dist <= max_radius_m:
            candidates.append((dist, park_key))
    if not candidates:
        return None
    return min(candidates)[1]


def _polyline_length_m(coords: List[List[float]]) -> float:
    return sum(
        _haversine_m(coords[i][1], coords[i][0], coords[i + 1][1], coords[i + 1][0])
        for i in range(len(coords) - 1)
    )


def fit_loop_to_target(coords: List[List[float]], target_m: Optional[float], tolerance: float = 1.25) -> List[List[float]]:
    """정적 공원 코스가 목표 거리보다 길면, 같은 보행로를 따라 갔다가 되돌아오는 왕복 코스로 줄인다.

    - 코스 길이가 목표의 tolerance 배 이내이면 그대로 둔다. (목표보다 짧은 코스도 늘리지 않는다.)
    - 새 좌표를 만들지 않고 검증된 원래 좌표만 쓰므로 공원 밖으로 나가지 않는다.
    - 출발점에서 목표 거리의 절반만큼 간 뒤 같은 길로 돌아와 출발점에서 끝난다.
    """
    if not target_m or target_m <= 0 or len(coords) < 2:
        return coords
    if _polyline_length_m(coords) <= target_m * tolerance:
        return coords
    half = target_m / 2.0
    out: List[List[float]] = [coords[0]]
    walked = 0.0
    for prev, cur in zip(coords, coords[1:]):
        step = _haversine_m(prev[1], prev[0], cur[1], cur[0])
        if walked + step >= half:
            break
        walked += step
        out.append(cur)
    if len(out) < 2:
        return coords
    return out + list(reversed(out[:-1]))


def match_pilot_park_loop(
    origin_lat: float,
    origin_lon: float,
    variant: int = 1,
    max_radius_m: float = 2500.0,
    pilot_park_id: Optional[str] = None,
) -> Optional[Tuple[List[List[float]], str]]:
    """공원 식별자 또는 출발 좌표를 기준으로 가장 적합한 실제 OSM 보행로 루프 반환."""
    best_key = resolve_pilot_park_key(origin_lat, origin_lon, max_radius_m, pilot_park_id)
    if best_key is None:
        return None
    best_name = PILOT_PARK_CENTERS[best_key][2]
    base_coords = PILOT_PARK_COORDS_MAP[best_key]

    if variant == 2:
        # 역방향 순환
        return (list(reversed(base_coords)), f"{best_name} (역방향 둘레길)")
    elif variant == 3:
        # 절반 지점 시작 순환 (방향 다변화)
        half = len(base_coords) // 2
        shifted = base_coords[half:] + base_coords[:half] + [base_coords[half]]
        return (shifted, f"{best_name} (수변 생태 연계 코스)")
    return (base_coords, best_name)
